-- AnySkill Marketplace Engine v0
-- PostgreSQL 10.23 compatible baseline.
-- UUID values are generated by the application/API to avoid extension assumptions.

BEGIN;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email varchar(320) NOT NULL,
  phone varchar(32),
  display_name varchar(120) NOT NULL,
  avatar_path text,
  account_status varchar(24) NOT NULL DEFAULT 'ACTIVE'
    CHECK (account_status IN ('ACTIVE','SUSPENDED','DEACTIVATED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_lower_uq ON users (lower(email));
CREATE UNIQUE INDEX users_phone_uq ON users (phone) WHERE phone IS NOT NULL;

CREATE TABLE skill_categories (
  id uuid PRIMARY KEY,
  name varchar(100) NOT NULL,
  slug varchar(120) NOT NULL UNIQUE,
  active boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE skills (
  id uuid PRIMARY KEY,
  category_id uuid NOT NULL REFERENCES skill_categories(id),
  name varchar(100) NOT NULL,
  slug varchar(120) NOT NULL UNIQUE,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX skills_category_idx ON skills(category_id);

CREATE TABLE professional_profiles (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  bio text,
  years_experience integer CHECK (years_experience IS NULL OR years_experience >= 0),
  verification_status varchar(20) NOT NULL DEFAULT 'UNVERIFIED'
    CHECK (verification_status IN ('UNVERIFIED','PENDING','VERIFIED','REJECTED')),
  is_online boolean NOT NULL DEFAULT false,
  accepting_jobs boolean NOT NULL DEFAULT false,
  service_radius_m integer NOT NULL DEFAULT 10000
    CHECK (service_radius_m BETWEEN 500 AND 100000),
  rating numeric(3,2) CHECK (rating IS NULL OR (rating >= 1 AND rating <= 5)),
  completed_jobs integer NOT NULL DEFAULT 0 CHECK (completed_jobs >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE professional_skills (
  id uuid PRIMARY KEY,
  professional_id uuid NOT NULL REFERENCES professional_profiles(user_id) ON DELETE CASCADE,
  skill_id uuid NOT NULL REFERENCES skills(id),
  title varchar(140),
  description text,
  base_price_minor bigint CHECK (base_price_minor IS NULL OR base_price_minor >= 0),
  currency char(3) NOT NULL DEFAULT 'ZAR',
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (professional_id, skill_id)
);
CREATE INDEX professional_skills_skill_idx ON professional_skills(skill_id, active);

CREATE TABLE professional_locations (
  professional_id uuid PRIMARY KEY REFERENCES professional_profiles(user_id) ON DELETE CASCADE,
  latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  area_label varchar(160),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX professional_locations_lat_lng_idx ON professional_locations(latitude, longitude);

CREATE TABLE job_requests (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES users(id),
  professional_id uuid NOT NULL REFERENCES professional_profiles(user_id),
  skill_id uuid NOT NULL REFERENCES skills(id),
  description text NOT NULL,
  budget_min_minor bigint CHECK (budget_min_minor IS NULL OR budget_min_minor >= 0),
  budget_max_minor bigint CHECK (budget_max_minor IS NULL OR budget_max_minor >= 0),
  currency char(3) NOT NULL DEFAULT 'ZAR',
  scheduled_for timestamptz,
  address_text text,
  latitude double precision CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  longitude double precision CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  status varchar(20) NOT NULL DEFAULT 'REQUESTED'
    CHECK (status IN ('REQUESTED','QUOTED','ACCEPTED','DECLINED','EXPIRED','CANCELLED')),
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (budget_min_minor IS NULL OR budget_max_minor IS NULL OR budget_min_minor <= budget_max_minor)
);
CREATE INDEX job_requests_professional_status_idx ON job_requests(professional_id, status, created_at);
CREATE INDEX job_requests_customer_idx ON job_requests(customer_id, created_at);

CREATE TABLE quotes (
  id uuid PRIMARY KEY,
  job_request_id uuid NOT NULL REFERENCES job_requests(id) ON DELETE CASCADE,
  professional_id uuid NOT NULL REFERENCES professional_profiles(user_id),
  amount_minor bigint NOT NULL CHECK (amount_minor >= 0),
  currency char(3) NOT NULL DEFAULT 'ZAR',
  note text,
  status varchar(20) NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING','ACCEPTED','DECLINED','SUPERSEDED','EXPIRED')),
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX quotes_request_idx ON quotes(job_request_id, created_at);

CREATE TABLE bookings (
  id uuid PRIMARY KEY,
  job_request_id uuid NOT NULL UNIQUE REFERENCES job_requests(id),
  customer_id uuid NOT NULL REFERENCES users(id),
  professional_id uuid NOT NULL REFERENCES professional_profiles(user_id),
  accepted_quote_id uuid REFERENCES quotes(id),
  agreed_amount_minor bigint NOT NULL CHECK (agreed_amount_minor >= 0),
  currency char(3) NOT NULL DEFAULT 'ZAR',
  status varchar(32) NOT NULL DEFAULT 'CONFIRMED'
    CHECK (status IN (
      'CONFIRMED','ON_THE_WAY','ARRIVED','IN_PROGRESS',
      'COMPLETION_SUBMITTED','CUSTOMER_CONFIRMED','PAYMENT_PROCESSING',
      'PAID','REVIEWED','CANCELLED','DISPUTED'
    )),
  scheduled_for timestamptz,
  started_at timestamptz,
  completion_submitted_at timestamptz,
  customer_confirmed_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bookings_customer_status_idx ON bookings(customer_id, status, created_at);
CREATE INDEX bookings_professional_status_idx ON bookings(professional_id, status, created_at);

CREATE TABLE booking_status_history (
  id uuid PRIMARY KEY,
  booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  from_status varchar(32),
  to_status varchar(32) NOT NULL,
  actor_id uuid REFERENCES users(id),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX booking_status_history_booking_idx ON booking_status_history(booking_id, created_at);

CREATE TABLE reviews (
  id uuid PRIMARY KEY,
  booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
  reviewer_id uuid NOT NULL REFERENCES users(id),
  reviewee_id uuid NOT NULL REFERENCES users(id),
  rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
  body text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (booking_id, reviewer_id),
  CHECK (reviewer_id <> reviewee_id)
);
CREATE INDEX reviews_reviewee_idx ON reviews(reviewee_id, created_at);

COMMIT;
